/// <summary>
/// The class <c>GUPPricingAttributeSourceDiscoveryAttribute</c> is used for tagging <c>PricingAttributeSource</c>.
/// </summary>
public class GUPPricingAttributeSourceDiscoveryAttribute extends SysAttribute implements SysExtensionIAttribute
{
    public GUPPricingAttributeSourceLevel level;
    public GUPPricingAttributeSource source;

}

Method.Source:
public void new(GUPPricingAttributeSource _source, GUPPricingAttributeSourceLevel _level)
{
    this.level = _level;
    this.source = _source;
}
